// Holographic Communicator - latency comparison (Mark 1 demonstration run)
// Run with: node demo.js
'use strict';
var lat=[4200,120,0.001];
console.log("Holographic Communicator - message latency by generation");
console.log("==================================================");
console.log("Light-speed reference: Earth-Mars ~ "+(12.5*60).toFixed(0)+" s one way at closest approach");
for(var m=0;m<3;m++){
  var l=lat[m], t=l<1?(l*1000).toFixed(2)+" us":l<1000?l.toFixed(1)+" ms":(l/1000).toFixed(2)+" s";
  console.log("Mark "+(m+1)+": "+t+" per hop, unlimited hops");
}
console.log("A conversation needing 10 exchanges: lightspeed Mars = hours; Mark III = milliseconds.");

